create extension if not exists pgcrypto;
create table if not exists public.events (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, title text not null, event_type text not null, event_date date, guest_count integer not null default 0 check (guest_count >= 0), budget numeric(14,2) not null default 0 check (budget >= 0), currency text not null default 'INR', location text, vibe text, status text not null default 'planning', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.event_tasks (id uuid primary key default gen_random_uuid(), event_id uuid not null references public.events(id) on delete cascade, title text not null, due_at timestamptz, category text, assigned_to uuid references auth.users(id) on delete set null, priority text not null default 'medium' check (priority in ('low','medium','high')), status text not null default 'todo' check (status in ('todo','in_progress','done')), created_at timestamptz not null default now());
create table if not exists public.event_expenses (id uuid primary key default gen_random_uuid(), event_id uuid not null references public.events(id) on delete cascade, category text not null, title text not null, estimated_amount numeric(14,2) not null default 0, actual_amount numeric(14,2) not null default 0, currency text not null default 'INR', payment_status text not null default 'estimated', created_at timestamptz not null default now());
create table if not exists public.event_vendors (id uuid primary key default gen_random_uuid(), event_id uuid not null references public.events(id) on delete cascade, google_place_id text, business_name text not null, category text, formatted_address text, phone_number text, website text, rating numeric(2,1), notes text, status text not null default 'shortlisted', created_at timestamptz not null default now());
create table if not exists public.event_guests (id uuid primary key default gen_random_uuid(), event_id uuid not null references public.events(id) on delete cascade, full_name text not null, email text, phone text, rsvp_status text not null default 'pending' check (rsvp_status in ('pending','confirmed','declined')), dietary_notes text, created_at timestamptz not null default now());
create table if not exists public.agent_runs (id uuid primary key default gen_random_uuid(), event_id uuid not null references public.events(id) on delete cascade, agent_name text not null, request_summary text not null, result jsonb not null default '{}'::jsonb, status text not null default 'proposed', created_at timestamptz not null default now());
create table if not exists public.action_approvals (id uuid primary key default gen_random_uuid(), event_id uuid not null references public.events(id) on delete cascade, agent_run_id uuid references public.agent_runs(id) on delete cascade, action_type text not null, action_payload jsonb not null default '{}'::jsonb, status text not null default 'pending', approved_by uuid references auth.users(id), approved_at timestamptz, created_at timestamptz not null default now());
 DO $$ declare t text; begin foreach t in array array['events','event_tasks','event_expenses','event_vendors','event_guests','agent_runs','action_approvals'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
create policy "owners manage own events" on public.events for all using (owner_id = auth.uid()) with check (owner_id = auth.uid());
create policy "owners manage event tasks" on public.event_tasks for all using (exists (select 1 from public.events e where e.id=event_id and e.owner_id=auth.uid())) with check (exists (select 1 from public.events e where e.id=event_id and e.owner_id=auth.uid()));
create policy "owners manage event expenses" on public.event_expenses for all using (exists (select 1 from public.events e where e.id=event_id and e.owner_id=auth.uid())) with check (exists (select 1 from public.events e where e.id=event_id and e.owner_id=auth.uid()));
create policy "owners manage event vendors" on public.event_vendors for all using (exists (select 1 from public.events e where e.id=event_id and e.owner_id=auth.uid())) with check (exists (select 1 from public.events e where e.id=event_id and e.owner_id=auth.uid()));
create policy "owners manage event guests" on public.event_guests for all using (exists (select 1 from public.events e where e.id=event_id and e.owner_id=auth.uid())) with check (exists (select 1 from public.events e where e.id=event_id and e.owner_id=auth.uid()));
create policy "owners manage agent runs" on public.agent_runs for all using (exists (select 1 from public.events e where e.id=event_id and e.owner_id=auth.uid())) with check (exists (select 1 from public.events e where e.id=event_id and e.owner_id=auth.uid()));
create policy "owners manage approvals" on public.action_approvals for all using (exists (select 1 from public.events e where e.id=event_id and e.owner_id=auth.uid())) with check (exists (select 1 from public.events e where e.id=event_id and e.owner_id=auth.uid()));
